function interleaveHalves(nums: number[], n: number): number[] {
  for (let i = 0; i < n; i++) nums[i] = (nums[n + i] << 10) | nums[i];
  // going backwards, slot 2i is never below i, so the packed slots 0..i-1 are still intact
  for (let i = n - 1; i >= 0; i--) {
    const packed = nums[i];
    nums[2 * i + 1] = packed >> 10;
    nums[2 * i] = packed & 1023;
  }
  return nums;
}

